  sfw_watch_contactor: { en: "Watch compressor and condenser fan operation after the call is satisfied.", es: "Vigila la operación del compresor y el ventilador del condensador después de satisfacer la llamada." },
  sfw_recheck_contactor1: { en: "Recheck line/load voltage and contact drop under load.", es: "Reverifica el voltaje de línea/carga y la caída de contacto bajo carga." },
  sfw_recheck_contactor2: { en: "Inspect wire heat damage and lug tightness after operation.", es: "Inspecciona el daño por calor en cables y el apriete de terminales después de operar." },
  sfw_risk_contactor: { en: "A new contactor can fail again if the real issue is motor/compressor load or wire heat.", es: "Un contactor nuevo puede volver a fallar si el problema real es la carga del motor/compresor o el calor en los cables." },
  sfw_watch_capacitor: { en: "Watch the motor/compressor start and run behavior after startup.", es: "Vigila el comportamiento de arranque y marcha del motor/compresor después del encendido." },
  sfw_recheck_capacitor1: { en: "Recheck actual µF if symptoms return.", es: "Reverifica los µF reales si los síntomas regresan." },
  sfw_recheck_capacitor2: { en: "Compare connected motor/compressor amp draw after the repair.", es: "Compara el consumo de amperaje del motor/compresor conectado después de la reparación." },
  sfw_risk_capacitor: { en: "Capacitors often fail again when the attached motor/compressor is weak.", es: "Los capacitores suelen volver a fallar cuando el motor/compresor conectado está débil." },
  sfw_watch_cond_fan: { en: "Watch head pressure trend and condenser airflow after repair.", es: "Vigila la tendencia de presión de descarga y el flujo de aire del condensador después de reparar." },
